const byte sensorPin = A0;
const float fixedResistor = 10000.0;
#if defined(ESP32)
const float supplyVoltage = 3.3;
const int adcMaximum = 4095;
#else
const float supplyVoltage = 5.0;
const int adcMaximum = 1023;
#endif

void setup() {
  Serial.begin(9600);
#if defined(ESP32)
  analogReadResolution(12);
#endif
}

void loop() {
  const int raw = analogRead(sensorPin);
  if (raw <= 0 || raw >= adcMaximum) {
    Serial.println("ADC is at a rail; check wiring and input range");
    delay(500);
    return;
  }
  const float voltage =
      static_cast<float>(raw) * supplyVoltage / adcMaximum;
  const float sensorResistance =
      fixedResistor * voltage / (supplyVoltage - voltage);
  Serial.print("ADC=");
  Serial.print(raw);
  Serial.print(" R=");
  Serial.println(sensorResistance);
  delay(500);
}
